import{_ as t,o,c as n,a0 as s}from"./chunks/framework.BQGW-Zpy.js";const u=JSON.parse('{"title":"Conclusion","description":"","frontmatter":{},"headers":[],"relativePath":"project/conclusion.md","filePath":"project/conclusion.md"}'),i={name:"project/conclusion.md"};function a(r,e,l,c,h,p){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h1><p>The strongest position in a red ocean is a clear one.</p><p>Cross-border payments is the most contested use case in the industry: Ripple since 2012, Stellar built for it, Circle, and Stripe paying roughly a billion dollars for Bridge, reportedly for the licences. We will not out-cover Wise, out-license Due, or out-spend Stripe, and we do not claim to.</p><p>Four claims carry this project:</p><ol><li><strong>Walletless on both sides.</strong> Not abstracted for a business, absent for the sender and the recipient. Zero crypto knowledge, at either end.</li><li><strong>Legal by construction.</strong> We hold nothing, so we need no licence. That is not a loophole; it is the model the EBA set out when the dual-licensing regime took effect in March 2026.</li><li><strong>The compliance trail is the gap.</strong> Every player in <a href="./../business/market-analysis.html">this section</a> leaves it inside one institution&#39;s database. Anchoring the hash with a consensus timestamp makes it verifiable by a party who trusts none of them.</li><li><strong>We say what does not work.</strong> Coverage is licensing. Capital lock-up moves rather than vanishes. Trading needs a different company. Stating those in the report is worth more than a claim an examiner can dismantle in one question.</li></ol><p>The most important architectural decision is the one that never appears on screen: <strong>we never touch the money.</strong> That single constraint is what makes the system legal, buildable in seven days, and clearly scoped.</p><hr>',7)])])}const m=t(i,[["render",a]]);export{u as __pageData,m as default};
